'use strict';

// Objects the adapter creates itself instead of declaring them in io-package.json "instanceObjects".
// js-controller writes instanceObjects again at every start, and after a reinstall the owner the user had set
// on chat.input (to let one dedicated user write requests) was gone. Objects created here are only extended:
// type, common and native are updated, the ACL is not part of the update.
// The names (eleven languages) are generated by tools/build-i18n.js into object-names.json.

const NAMES = require('./object-names.json');

const OBJECTS = [
    { id: 'chat', type: 'channel', common: {} },
    {
        id: 'chat.input',
        type: 'state',
        common: { type: 'string', role: 'text', read: true, write: true, def: '' },
    },
    {
        id: 'chat.answer',
        type: 'state',
        common: { type: 'string', role: 'text', read: true, write: false, def: '' },
    },
    {
        id: 'chat.pending',
        type: 'state',
        common: { type: 'string', role: 'json', read: true, write: false, def: '' },
    },
    { id: 'usage', type: 'channel', common: {} },
    {
        id: 'usage.tokensInput',
        type: 'state',
        common: { type: 'number', role: 'value', unit: 'tokens', read: true, write: false, def: 0 },
    },
    {
        id: 'usage.tokensOutput',
        type: 'state',
        common: { type: 'number', role: 'value', unit: 'tokens', read: true, write: false, def: 0 },
    },
    {
        id: 'usage.tokensTotal',
        type: 'state',
        common: { type: 'number', role: 'value', unit: 'tokens', read: true, write: false, def: 0 },
    },
    {
        id: 'usage.cost',
        type: 'state',
        common: { type: 'number', role: 'value', unit: 'USD', read: true, write: false, def: 0 },
    },
    { id: 'usage.json', type: 'state', common: { type: 'string', role: 'json', read: true, write: false, def: '' } },
    { id: 'backup', type: 'channel', common: {} },
    {
        id: 'backup.last',
        type: 'state',
        common: { type: 'number', role: 'date', read: true, write: false, def: 0 },
    },
    {
        id: 'backup.size',
        type: 'state',
        common: { type: 'number', role: 'value', unit: 'bytes', read: true, write: false, def: 0 },
    },
    {
        id: 'backup.lastRemote',
        type: 'state',
        common: { type: 'string', role: 'text', read: true, write: false, def: '' },
    },
    {
        id: 'backup.remoteError',
        type: 'state',
        common: { type: 'string', role: 'text', read: true, write: false, def: '' },
    },
    { id: 'memory', type: 'channel', common: {} },
    // the user may edit the facts here; the adapter takes them over and confirms with ack
    { id: 'memory.list', type: 'state', common: { type: 'string', role: 'json', read: true, write: true, def: '[]' } },
    {
        id: 'memory.count',
        type: 'state',
        common: { type: 'number', role: 'value', read: true, write: false, def: 0 },
    },
    { id: 'scheduled', type: 'channel', common: {} },
    {
        id: 'scheduled.watches',
        type: 'state',
        common: { type: 'string', role: 'json', read: true, write: false, def: '[]' },
    },
    { id: 'telegram', type: 'channel', common: {} },
    {
        id: 'telegram.chats',
        type: 'state',
        common: { type: 'string', role: 'json', read: true, write: false, def: '' },
    },
];

/**
 * Create or update the adapter's own objects without touching their ACL.
 *
 * @param {{ extendObjectAsync: (id: string, obj: object) => Promise<unknown> }} adapter running adapter
 */
async function ensureObjects(adapter) {
    for (const { id, type, common } of OBJECTS) {
        const name = NAMES[id];
        if (!name) {
            throw new Error(`No translated name for object ${id}`);
        }
        await adapter.extendObjectAsync(id, { type, common: { ...common, name }, native: {} });
    }
}

module.exports = { OBJECTS, ensureObjects };
